function DebugBoxMovePanel:__init()
    self.controller = nil

    self.humanTF = nil   -- Transform
    self.catTF = nil -- Transform

    self.mCameraTF = nil -- Transform

    self.isLeftPress = false
    self.isRightPress = false
    self.isForwardPress = false
    self.isBackPress = false
    self.isUpPress = false
    self.isDownPress = false

    self.isInit = false
end


function DebugBoxMovePanel:__delete()
end



function DebugBoxMovePanel:Awake()
    KTool.SetActive(self.controller.gameObject, true)

    self.gameObject = self.controller.gameObject
end



function DebugBoxMovePanel:Start()
    KTool.SetActive(self.controller.gameObject, true);

    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ============================== 
end



function DebugBoxMovePanel:Init(debugBox_, humanTF_, catTF_, mCamera_)
    if DebugBox.IsTotalActive() == false then
        return
    end

    self.debugBox = debugBox_    -- DebugBox
    self.humanTF = humanTF_
    self.catTF = catTF_
    self.mCameraTF = mCamera_.transform

    assert( self.leftTrigger and self.rightTrigger and self.forwardTrigger and self.backTrigger and self.upTrigger and self.downTrigger )


    self.WhenDownFunc = function(eventData)
        self:WhenDown(eventData)
    end

    self.WhenUpFunc = function(eventData)
        self:WhenUp(eventData)
    end

    DreamSpaceUtils.AddEventTriggerListener(self.leftTrigger, EventTriggerType.PointerDown, self.WhenDownFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.rightTrigger, EventTriggerType.PointerDown, self.WhenDownFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.forwardTrigger, EventTriggerType.PointerDown, self.WhenDownFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.backTrigger, EventTriggerType.PointerDown, self.WhenDownFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.upTrigger, EventTriggerType.PointerDown, self.WhenDownFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.downTrigger, EventTriggerType.PointerDown, self.WhenDownFunc)

    DreamSpaceUtils.AddEventTriggerListener(self.leftTrigger, EventTriggerType.PointerUp, self.WhenUpFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.rightTrigger, EventTriggerType.PointerUp, self.WhenUpFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.forwardTrigger, EventTriggerType.PointerUp, self.WhenUpFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.backTrigger, EventTriggerType.PointerUp, self.WhenUpFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.upTrigger, EventTriggerType.PointerUp, self.WhenUpFunc)
    DreamSpaceUtils.AddEventTriggerListener(self.downTrigger, EventTriggerType.PointerUp, self.WhenUpFunc)

    ---
    self.isInit = true
    print("koko - debugBox - MovePanel 初始化完成")
end



function DebugBoxMovePanel:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function DebugBoxMovePanel:Update()
    if DebugBox.IsTotalActive() == false then
        return
    end
    ---
    if self.isLeftPress then
        self:DoMove(-moveSpeed * Time.deltaTime, 0, 0)
    elseif self.isRightPress then
        self:DoMove(moveSpeed * Time.deltaTime, 0, 0)
    end

    if self.isForwardPress then
        self:DoMove(0, 0, moveSpeed * Time.deltaTime)
    elseif self.isBackPress then
        self:DoMove(0, 0, -moveSpeed * Time.deltaTime)
    end

    if self.isUpPress then
        self:DoMove(0, moveSpeed * Time.deltaTime, 0)
    elseif self.isDownPress then
        self:DoMove(0, -moveSpeed * Time.deltaTime, 0)
    end
end




-- =========================================== Self ================================================ --



function DebugBoxMovePanel:WhenDown(eventData)
    self:HandlePressChange(eventData, true)
end

function DebugBoxMovePanel:WhenUp(eventData)
    self:HandlePressChange(eventData, false)
end


function DebugBoxMovePanel:HandlePressChange(eventData, isPress)
    local selectedObject = eventData.selectedObject
    --:

    local idComp = KTool.GetComponent(selectedObject, typeof(ID))
    assert( idComp )
    local direction = idComp.stringId -- string
    assert( #direction > 0 )

    self:SetPress(direction, isPress)

    -- local comp = selectedObject.transform:GetComponent(typeof(DebugBoxMoveDirectionButton))
    -- if comp ~= nil then
    --     SetPress(comp.direction, isPress)
    -- else
    --     Debug.LogError(selectedObject.name .. " 没找到 DebugBoxMoveDirectionButton 组件")
    -- end
end


-- dir string
function DebugBoxMovePanel:SetPress(dir, isPress)
    if dir == "Left" then
        self.isLeftPress = isPress
    elseif dir == "Right" then
        self.isRightPress = isPress
    elseif dir == "Forward" then
        self.isForwardPress = isPress
    elseif dir == "Back" then
        self.isBackPress = isPress
    elseif dir == "Up" then
        self.isUpPress = isPress
    elseif dir == "Down" then
        self.isDownPress = isPress
    else
        assert(false)
    end
end


function DebugBoxMovePanel:DoMove(x, y, z)
    local offset = self:GetMoveOffset(x, y, z)
    self.humanTF.position = self.humanTF.position + offset
    self.catTF.position = self.catTF.position + offset
end


function DebugBoxMovePanel:GetMoveOffset(x, y, z)
    local forward = Vector3.ProjectOnPlane(self.mCameraTF.forward, Vector3.up)
    local up = Vector3.up
    local right = Vector3.Cross(up, forward)
    return right * x + up * y + forward * z
end





return DebugBoxMovePanel

